// Bases
int decimal_val = 10;
int hex_val = 0xA;      // 16
int octal_val = 012;    // 8 + 2 = 10
int binary_val = 0b101; // C++14 / C11

// Suffixes (Type Specification)
unsigned int u_val = 100U;
long l_val = 50L;
long long ll_val = 123456789LL;
unsigned long ul_val = 400UL;

// Minimum guaranteed width (C++11/C99)
int64_t large_num = 5000000000LL;

// C++14 Digit Separators
int big_val = 1'000'000;
int hex_mask = 0xFF'FF'00'00;
